      - name: Publish the edge release
        env:
          GH_TOKEN: ${{ github.token }}
          VERSION: ${{ needs.version.outputs.version }}
        run: |
          tag="v$VERSION"
          # Already published, as when a run is re-run: nothing more to do.
          if gh release view "$tag" --repo "$GITHUB_REPOSITORY" > /dev/null 2>&1; then
            echo "$tag is already published."
            exit 0
          fi
          short=$(git rev-parse --short "$GITHUB_SHA")
          subject=$(git log -1 --format=%s "$GITHUB_SHA")
          notes="[\`$short\`]($GITHUB_SERVER_URL/$GITHUB_REPOSITORY/commit/$GITHUB_SHA) $subject"
          gh release create "$tag" dist/* \
            --repo "$GITHUB_REPOSITORY" \
            --target "$GITHUB_SHA" \
            --title "Suspense $VERSION (edge)" \
            --notes "$notes" \
            --latest
